527	// One 64-col output box: (CN/16)x m64n64k16 wgmma accumulating into acc[O..O+31] (O compile-time).
528	// NO fence/commit here -- pv_boxes wraps ALL boxes in ONE wgmma group (single fence + single commit) so
529	// the whole PV is a single in-flight group. That lets wgmma_wait1 leave the ENTIRE PV overlapping the
530	// softmax (FA3's 2-group QK/PV pipeline). Per-box commit (the old form) left only the LAST box in flight
531	// after wait1, so softmax overlapped just 1/N of the PV -> tensor pipe 35% vs FA3 56%.
532	template <typename T, int O, int N, int CN>
533	__device__ __forceinline__ void pv_box64_body(float (&acc)[N], const uint32_t (&P)[CN/4], uint64_t baseV) {
534	#pragma unroll
535	    for (int kb = 0; kb < CN / 16; ++kb) {
536	        uint64_t dB = desc_add(baseV, (uint32_t)v_doff(kb));
537	        if constexpr (is_f16<T>())
