611	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
612	__device__ __forceinline__ void qk_rs_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
613	                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
614	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
