cd /home/yak/fa3-cuda; echo "=== MUFU.RCP addresses (runtime division markers) ==="; grep -E "MUFU.RCP" /tmp/pf_pow2.sass | grep -oE "/\*[0-9a-f]+\*/" ; echo; echo "=== loop body 0x3fe0-0x6e60: instruction class counts ==="; python3 - <<'EOF'
import re
lines=open('/tmp/pf_pow2.sass').read().splitlines()
inloop=False; cnt={}
for l in lines:
    m=re.search(r'/\*([0-9a-f]+)\*/\s+@?!?P?T?[0-9]?\s*([A-Z][A-Za-z0-9._]+)',l)
    if not m: continue
    a=int(m.group(1),16); op=m.group(2)
    if 0x3fe0<=a<=0x6e60:
        cnt[op]=cnt.get(op,0)+1
for k,v in sorted(cnt.items(),key=lambda x:-x[1]):
    print(f"{v:4d} {k}")
EOF

